Restrict CloudWatch Logs permissions to specific log groups:

lambda_role.add_to_policy(
    iam.PolicyStatement(
        actions=[
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
        ],
        resources=[
            f"arn:aws:logs:{self.region}:{self.account}:log-group:/aws/lambda/ConnectAcgrReplicator*",
        ],
    )
)

