Enforce encryption at rest for all S3 buckets regardless of source configuration. Change the code to:

```python
# Always enable encryption (use source type if available, otherwise default to AES256)
encryption_type = getattr(resource, "encryption_type", None) or "AES256"
try:
    s3_client.put_bucket_encryption(
        Bucket=target_name,
        ServerSideEncryptionConfiguration={
            "Rules": [
                {
                    "ApplyServerSideEncryptionByDefault": {
                        "SSEAlgorithm": encryption_type,
                    },
                    "BucketKeyEnabled": True
                }
            ]
        },
    )
    logger.info("Applied %s encryption to bucket '%s'", encryption_type, target_name)
except Exception:
    logger.error("Failed to apply encryption to bucket '%s' - this is a security requirement", target_name)
    raise  # Fail replication if encryption cannot be applied
```

For production use, consider using SSE-KMS with customer-managed keys instead of SSE-S3 (AES256) for better key management and audit capabilities.

Enable S3 server access logging for all replicated buckets. Add this code after line 159 in the replicate_s3_bucket function:

```python
# Enable access logging for audit trail
try:
    # Create or identify a logging bucket (should be created once per account/region)
    logging_bucket = f"{target_name}-logs"
    try:
        s3_client.head_bucket(Bucket=logging_bucket)
    except s3_client.exceptions.ClientError:
        # Create logging bucket if it doesn't exist
        create_params_log = {"Bucket": logging_bucket}
        if target_region != "us-east-1":
            create_params_log["CreateBucketConfiguration"] = {"LocationConstraint": target_region}
        s3_client.create_bucket(**create_params_log)
        s3_client.put_public_access_block(
            Bucket=logging_bucket,
            PublicAccessBlockConfiguration={
                "BlockPublicAcls": True,
                "IgnorePublicAcls": True,
                "BlockPublicPolicy": True,
                "RestrictPublicBuckets": True,
            },
        )

    s3_client.put_bucket_logging(
        Bucket=target_name,
        BucketLoggingStatus={
            "LoggingEnabled": {
                "TargetBucket": logging_bucket,
                "TargetPrefix": f"{target_name}/",
            }
        },
    )
    logger.info("Enabled access logging for bucket '%s'", target_name)
except Exception:
    logger.error("Failed to enable access logging for bucket '%s'", target_name, exc_info=True)
    # Consider whether to fail replication or continue with warning
