Validate instance_arn format before use. Example:

import re

ARN_PATTERN = re.compile(
    r"^arn:aws:connect:[a-z0-9-]+:\d{12}:instance/[a-f0-9-]+$"
)

if not ARN_PATTERN.match(instance_arn):
    raise ValueError(
        f"Invalid Connect instance ARN format: {instance_arn}. "
        f"Expected format: arn:aws:connect:REGION:ACCOUNT:instance/INSTANCE_ID"
    )

Wrap the associate_approved_origin call in a try/except block to handle potential AWS API errors gracefully. Example:

try:
    connect_client.associate_approved_origin(
        InstanceId=target_instance_id,
        Origin=origin_url,
    )
except ClientError as exc:
    logger.error("Failed to associate approved origin: %s", exc)
    raise RuntimeError(f"Failed to associate origin {origin_url}: {exc}") from exc

Validate origin_url format before use. Example:

from urllib.parse import urlparse

origin_url = (
    getattr(resource, "origin_url", None)
    or resource.config_summary.get("origin_url")
    or resource.name
)

if not origin_url:
    raise ValueError("origin_url is required but not found")

try:
    parsed = urlparse(origin_url)
    if not parsed.scheme or not parsed.netloc:
        raise ValueError(f"Invalid origin URL format: {origin_url}")
except Exception as exc:
    raise ValueError(f"Invalid origin URL: {exc}") from exc

